// ── Scorecard row for DataTable 1 (Question Evaluation) ──────────────────────
export interface QuestionScoreRow {
  criteria: string;
  [interviewer: string]: string | number; // interviewer_1, interviewer_2 …
}

// ── Scorecard row for DataTable 2 (Overall Evaluation) ───────────────────────
export interface OverallScoreRow {
  criteria: string;
  total: number;
  [interviewer: string]: string | number;
}

// ── Action / form state ───────────────────────────────────────────────────────
export interface ActionValue {
  CandidateStatus: string;
  Comments: string;
}

export interface ValidationError {
  Comments: boolean;
  Checkboxalidation: boolean;
  CandidateStatus: boolean;
  PositionID: boolean;
}

export interface FieldsEditable {
  radioGroup: boolean;
  comments: boolean;
  visibleButtons: string[]; // "Selected" | "Rejected" | "OnHold"
}

export interface InterviewedLevelValue {
  Levels: string;
  Grade: string;
}

